#!/bin/zsh
set -euo pipefail

# Reproduce the four-protein comparison. Existing source artifacts are never
# overwritten; delete or move them deliberately if a fresh network download is
# required. Derived alignment/results files are regenerated by the Python step.

run_root="${0:A:h}"
sequence_dir="${run_root}/sequences"
record_dir="${run_root}/records"
source_dir="${run_root}/sources"

mkdir -p "${sequence_dir}" "${record_dir}" "${source_dir}"

fetch_if_missing() {
  local url="$1"
  local destination="$2"
  if [[ -e "${destination}" ]]; then
    print -u2 "retaining existing source artifact: ${destination}"
    return 0
  fi
  curl -fsSL "${url}" -o "${destination}"
}

fetch_if_missing \
  "https://rest.uniprot.org/uniprotkb/P08539.fasta" \
  "${sequence_dir}/ScGpa1_P08539.fasta"
fetch_if_missing \
  "https://rest.uniprot.org/uniprotkb/P10823.fasta" \
  "${sequence_dir}/ScGpa2_P10823.fasta"
fetch_if_missing \
  "https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi?db=protein&id=TGJ64397.1&rettype=fasta&retmode=text" \
  "${sequence_dir}/AoGpa2_TGJ64397.1.fasta"
fetch_if_missing \
  "https://rest.uniprot.org/uniprotkb/A0A436ZRX2.fasta" \
  "${sequence_dir}/AfGasA_A0A436ZRX2.fasta"

fetch_if_missing \
  "https://rest.uniprot.org/uniprotkb/P08539.txt" \
  "${record_dir}/P08539_uniprot.txt"
fetch_if_missing \
  "https://rest.uniprot.org/uniprotkb/P10823.txt" \
  "${record_dir}/P10823_uniprot.txt"
fetch_if_missing \
  "https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi?db=protein&id=TGJ64397.1&rettype=gb&retmode=text" \
  "${record_dir}/TGJ64397.1_genbank.txt"
fetch_if_missing \
  "https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi?db=protein&id=TGJ64397.1&rettype=fasta_cds_na&retmode=text" \
  "${record_dir}/TGJ64397.1_cds.fna"
fetch_if_missing \
  "https://rest.uniprot.org/uniprotkb/A0A436ZRX2.txt" \
  "${record_dir}/A0A436ZRX2_uniprot.txt"
fetch_if_missing \
  "https://www.ncbi.nlm.nih.gov/sviewer/viewer.fcgi?id=RVD81648.1&db=protein&report=fasta&retmode=text" \
  "${record_dir}/RVD81648.1_ncbi.fasta"
fetch_if_missing \
  "https://www.ncbi.nlm.nih.gov/sviewer/viewer.fcgi?id=RVD81648.1&db=protein&report=genbank&retmode=text" \
  "${record_dir}/RVD81648.1_genbank.txt"
fetch_if_missing \
  "https://www.ncbi.nlm.nih.gov/sviewer/viewer.fcgi?id=RVD81648.1&db=protein&report=fasta_cds_na&retmode=text" \
  "${record_dir}/RVD81648.1_cds.fna"

fetch_if_missing \
  "https://media.springernature.com/original/springer-static/esm/art%3A10.1038%2Fs41564-024-01679-w/MediaObjects/41564_2024_1679_MOESM4_ESM.xlsx" \
  "${source_dir}/Kuo2024_Supplementary_Tables_1-4.xlsx"
fetch_if_missing \
  "https://pmc.ncbi.nlm.nih.gov/articles/PMC11222155/?report=xml" \
  "${source_dir}/Hu2024_PMC11222155.html"
fetch_if_missing \
  "https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi?db=biosample&id=SAMN10185917&retmode=xml" \
  "${source_dir}/SAMN10185917.xml"
fetch_if_missing \
  "https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi?db=pmc&id=6453484&retmode=xml" \
  "${source_dir}/Youssar2019_PMC6453484.xml"

analysis_python="${ANALYSIS_PYTHON:-/opt/homebrew/Caskroom/miniforge/base/envs/chimeric/bin/python}"
clustalo_bin="${CLUSTALO_BIN:-/opt/homebrew/Caskroom/miniforge/base/envs/chimeric/bin/clustalo}"

"${analysis_python}" "${run_root}/analyze_sequences.py" --clustalo "${clustalo_bin}"

(
  cd "${run_root}"
  shasum -a 256 -c checksums.sha256
)
